using Test

# === EXAMPLE A ===
function worked_a()
    values = collect(1:6)
    matrix = reshape(values, 2, 3)
    @test size(matrix) == (2, 3)
    @test matrix[:, 1] == [1, 2]
    @test matrix[1, 3] == 5
    @test length(matrix) == 6
    @test sum(matrix) == 21
    println("Matrix: ", matrix)
end

# === EXAMPLE B ===
function worked_b()
    values = [1, 2, 3]
    snapshot = values[1:2]
    window = @view values[1:2]
    snapshot[1] = 90
    @test values[1] == 1
    window[2] = 80
    @test values == [1, 80, 3]
    alias = values
    @test alias === values
    @test copy(values) !== values
    println("Source after view mutation: ", values)
end

# === EXERCISES ===
function exercise_checks()
    @test size(zeros(2, 1)) == (2, 1)
    @test size(zeros(2)) == (2,)
    @test eltype([1.0, 2.0]) == Float64
    @test_throws BoundsError [1, 2][0]
    nested = [[1], [2]]
    shallow = copy(nested)
    shallow[1][1] = 9
    @test nested[1][1] == 9
    deep = deepcopy(nested)
    deep[1][1] = 4
    @test nested[1][1] == 9
end

# === EXAMPLE A ===
function worked_a()
    shapes = Shape[Circle(2), Rectangle(2, 3)]
    @test area(shapes[1]) ≈ 4pi
    @test area(shapes[2]) == 6
    @test total_area(shapes) ≈ 4pi + 6
    @test total_area(Shape[]) == 0
    println("Total area: ", total_area(shapes))
end

# === EXAMPLE B ===
function worked_b()
    @test classify(1, "x") == :first_integer
    @test classify("x", 1) == :second_integer
    @test classify(1, 2) == :both_integers
    @test_throws MethodError classify(1.0, 2.0)
    println("Intersection method: ", classify(1, 2))
end

# === EXERCISES ===
function exercise_checks()
    @test area(Circle(0)) == 0
    @test area(Rectangle(0, 5)) == 0
    @test_throws ArgumentError Circle(-1)
    @test_throws ArgumentError Rectangle(1, -1)
    @test Circle <: Shape
    @test isconcretetype(Circle) && !isconcretetype(Shape)
end

# === MAIN ===
function main()
    worked_a()
    worked_b()
    exercise_checks()
    println("julia-011: all reference checks passed")
end

if abspath(PROGRAM_FILE) == @__FILE__
    main()
end

# === EXAMPLE A ===
function worked_a()
    matrix = [2.0 1.0; 0.0 3.0]
    input = [3.0, 4.0]
    bias = [1.0, -1.0]
    destination = zeros(2)
    @test affine!(destination, matrix, input, bias) === destination
    @test destination == [11, 11]
    @test input == [3, 4]
    affine!(destination, matrix, [1.0, 2.0], bias)
    @test destination == [5, 5]
    bytes = @allocated affine!(destination, matrix, input, bias)
    @test bytes >= 0
    println("Reused output: ", destination, "; measured allocation bytes: ", bytes)
end

# === EXERCISES ===
function exercise_checks()
    output = fill(7.0, 2)
    @test_throws DimensionMismatch affine!(output, ones(2, 3), ones(2), ones(2))
    @test output == [7, 7]
    @test_throws ArgumentError affine!(output, Matrix{Float64}(I, 2, 2), ones(2), output)
    @test affine!(zeros(2), [1.0 2.0; 3.0 4.0], [2.0, 1.0], [0.0, 0.0]) == [4, 10]
    original = [1.0, 2.0]
    separate = copy(original)
    separate[1] = 9
    @test original == [1, 2]
end

# === MAIN ===
function main()
    worked_a()
    worked_b()
    exercise_checks()
    println("julia-026: all reference checks passed")
end

if abspath(PROGRAM_FILE) == @__FILE__
    main()
end
